const start = $now.setZone('Asia/Jerusalem').minus({ months: 1 }).startOf('month').toFormat('yyyy-MM-dd');
const end = $now.setZone('Asia/Jerusalem').startOf('month').toFormat('yyyy-MM-dd');
const rows = $input.all().map(i => i.json).filter(t => t.date_local >= start && t.date_local < end);
const lines = rows.map(t => `${t.date_local}\t${t.description}\t${t.chargedAmount}\t${t.category || ''}`);
return [{ json: { month: start.slice(0, 7), count: rows.length, transactions: lines.join('\n') } }];

